/// <summary>
/// designed rom AVA
/// </summary>
[ExtensionOf(classStr(SalesTableType))]
final class AVASalesTableType_Extension
{
}

Method.Source:
/// <summary>
/// designed from AVA
/// </summary>
/// <returns>boolean</returns>
public boolean AVACanTypeBeChanged()
{

    boolean               ok = true;

    if (!salesTable.AVACheckInfoField2())
    {
        ok = checkFailed("@NDX:NXAInfo2Error");
    }

    ok = salesTable.AVAValidateTaxGroup() && ok;

    if (!salesTable.AVAcheckCentralWarehaus())
    {
        ok = checkFailed("@NDX:NXACentralWarehousError");
    }

    salesTable.checkPreferenceAuth();

    salesTable.checkMissedPriceAgreement();

    ok = ok && salesTable.avaCheckLinePAInfo();
    ok = ok && salesTable.checkNullQuantity();

    ok = ok && salesTable.AVACheckRepPckSlipNum();
    ok = ok && salesTable.avaCheckEDIGLN();

    ok = ok && !salesTable.avaIsCommercialAgentOrigin();

    ok = ok && salesTable.AVAckeclCustCredManBlock();

    ok = ok && salesTable.checkLineColor();

    return ok;
}

/// <summary>
/// designed from AVA
/// </summary>
/// <returns>boolean</returns>
public boolean AVAJournalApprovalChangeCheck()
{
    boolean ok = true;

    // Info2
    if (!salesTable.AVACheckInfoField2())
    {
        ok = checkFailed("@NDX:NXAInfo2Error");
    }

    // Zentrallager
    if (!salesTable.AVAcheckCentralWarehaus())
    {
        ok = checkFailed("@NDX:NXACentralWarehousError");
    }

    // PA Info
    ok = ok && salesTable.avaCheckLinePAInfo();

    // Doppelte Bestellnummer
    ok = ok && salesTable.AVACheckPODublicate();

    ok = ok && salesTable.AVAckeclCustCredManBlock();

    //Check Color
    ok = ok && salesTable.checkLineColor();

    // Preis 0
    salesTable.checkMissedPriceAgreement();

    //Präferenzprüfung
    salesTable.checkPreferenceAuth();

    if (!salesTable.AVAcheckQuotationStatus())
    {
        warning("@NDX:NXAQuotationStatusFailed");
    }

    return ok;
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_salesTable">_salesTable</param>
/// <param name = "_purchTable">_purchTable</param>
/// <param name = "_forceAddressSync">_forceAddressSync</param>
/// <returns>syncPurchTable</returns>
AxPurchTable syncPurchTable(SalesTable _salesTable, PurchTable _purchTable, boolean _forceAddressSync)
{
    AxPurchTable        locAxPurchTable = next syncPurchTable(_salesTable,_purchTable,_forceAddressSync);

    if (_salesTable.KCS_FreightCostStatus != KCS_FreightCostStatus::Calculated)
    {
        locAxPurchTable.parmAvaKCS_FreightCostStatus(_salesTable.KCS_FreightCostStatus);
    }
    locAxPurchTable.parmAvaKCS_POC_CarriageFree(_salesTable.KCS_POC_CarriageFree);
    locAxPurchTable.parmAvaKCS_FreightCalculation(_salesTable.KCS_FreightCalculation);
    locAxPurchTable.parmAvaKCS_FreightChargeFree(_salesTable.KCS_FreightChargeFree);
    locAxPurchTable.parmAvaKCS_FreightCosts(_salesTable.KCS_FreightCosts);
    locAxPurchTable.parmAVADlvResponsible(_salesTable.AVADlvResponsible);

    locAxPurchTable.parmAVAShipCarrierDeliveryContact(_salesTable.AVAShipCarrierDeliveryContact);
    locAxPurchTable.parmNDX_ShipCarrierDeliveryEmail(_salesTable.NDX_ShipCarrierDeliveryEmail);
    locAxPurchTable.parmNDX_ShipCarrierDeliveryPhone(_salesTable.NDX_ShipCarrierDeliveryPhone);
    locAxPurchTable.parmAVAShipCarrierDeliveryMobile(_salesTable.AVAShipCarrierDeliveryMobile);
    locAxPurchTable.parmInventSiteId(_salesTable.InventSiteId);

    return locAxPurchTable;

}
